CARDIO.register({"item":"p359","meta":{"num":"p359","label":"359","spe":"pneumo","short":"Détresse respiratoire","title":"Détresse respiratoire de l'adulte","section":"P","chapter":20,"pages":"316-329","sdd":[]},"objectives":[{"id":"p359-obj-01","rank":"A","rubric":"Contenu multimédia","title":"Savoir reconnaître un OAP sur une radiographie du thorax","desc":""},{"id":"p359-obj-02","rank":"A","rubric":"Contenu multimédia","title":"Savoir reconnaître une pneumonie sur une radiographie du thorax","desc":""},{"id":"p359-obj-03","rank":"A","rubric":"Définition","title":"Définition de la détresse et de l'insuffisance respiratoire aiguë","desc":""},{"id":"p359-obj-04","rank":"A","rubric":"Définition","title":"Critères de diagnostic, variations avec l'âge","desc":""},{"id":"p359-obj-05","rank":"A","rubric":"Diagnostic positif","title":"Savoir rechercher les éléments d'orientation clinique et anamnestique devant une insuffisance respiratoire aiguë chez l'adulte","desc":""},{"id":"p359-obj-06","rank":"B","rubric":"Éléments physiopathologiques","title":"Principes physiopathologiques de l'hypoxémie","desc":""},{"id":"p359-obj-07","rank":"B","rubric":"Éléments physiopathologiques","title":"Anomalies de la pompe ventilatoire","desc":""},{"id":"p359-obj-08","rank":"B","rubric":"Éléments physiopathologiques","title":"Éléments physiopathologiques du SDRA et causes principales","desc":""},{"id":"p359-obj-09","rank":"A","rubric":"Étiologies","title":"Savoir reconnaître les causes les plus fréquentes chez l'adulte","desc":""},{"id":"p359-obj-10","rank":"A","rubric":"Examens complémentaires","title":"Stratégie d'investigations à visée étiologique pour les hypothèses fréquentes (décompensation de BPCO, OAP, EP, PNP, asthme, bronchiolites, pathologies des voies aériennes supérieures)","desc":""},{"id":"p359-obj-11","rank":"A","rubric":"Identifier une urgence","title":"Reconnaître les signes de gravité cliniques et gazométriques","desc":""},{"id":"p359-obj-12","rank":"A","rubric":"Identifier une urgence","title":"Savoir orienter en urgence un patient en détresse respiratoire aiguë pour un geste spécialisé","desc":""},{"id":"p359-obj-13","rank":"A","rubric":"Prise en charge","title":"Connaître les modalités d'oxygénation initiale","desc":""},{"id":"p359-obj-14","rank":"B","rubric":"Prise en charge","title":"Connaître les différents moyens de la prise en charge d'un patient en insuffisance respiratoire aiguë","desc":""},{"id":"p359-obj-15","rank":"A","rubric":"Identifier une urgence","title":"Reconnaître les signes de détresse respiratoire suite à une inhalation d'un corps étranger, ou en cas d'épiglottite","desc":""},{"id":"p359-obj-16","rank":"A","rubric":"Prise en charge","title":"Connaître les premiers gestes chez l'adulte présentant une inhalation de corps étranger","desc":""}],"course":{"sections":[],"essentials":[],"numbers":[],"mnemonics":[]},"questions":[{"id":"p359-qroc-001","type":"QROC","rank":"A","objective":"p359-obj-03","tags":["définition","clinique"],"difficulty":1,"question":"Les signes cliniques de détresse respiratoire aiguë se répartissent en deux groupes : lesquels ?","answer":"Les signes de lutte et les signes de faillite","accept":["lutte et faillite","signes de lutte, signes de faillite","lutte, faillite","lutte puis faillite"],"keywords":["lutte","faillite"],"explanation":"Les signes de lutte traduisent l'augmentation du travail ventilatoire ; les signes de faillite traduisent la défaillance du système. Les deux coexistent, mais un seul signe de faillite suffit à signer la gravité.","src":"p. 317"},{"id":"p359-qroc-002","type":"QROC","rank":"A","objective":"p359-obj-03","tags":["définition","biologie"],"difficulty":1,"question":"Quelle valeur de PaO2 définit l'hypoxémie profonde de l'insuffisance respiratoire aiguë ?","answer":"PaO2 < 60 mmHg","accept":["60 mmHg","inférieure à 60 mmHg","moins de 60 mmHg","60"],"keywords":["60"],"explanation":"L'insuffisance respiratoire aiguë est le versant gazométrique de la détresse : hypoxémie profonde (PaO2 < 60 mmHg) avec modification du pH, notamment acidose respiratoire hypercapnique.","src":"p. 317"},{"id":"p359-qroc-003","type":"QROC","rank":"A","objective":"p359-obj-03","tags":["définition","biologie"],"difficulty":1,"question":"Quelle valeur de PaCO2 définit l'hypercapnie dans l'insuffisance respiratoire aiguë ?","answer":"PaCO2 > 45 mmHg","accept":["45 mmHg","supérieure à 45 mmHg","plus de 45 mmHg","≥ 45 mmHg","45"],"keywords":["45"],"explanation":"L'acidose respiratoire avec hypercapnie traduit une hypoventilation alvéolaire. Le chapitre reprend ce seuil de 45 mmHg (avec un pH anormal) pour évoquer la décompensation d'une maladie respiratoire chronique.","src":"p. 317, 326"},{"id":"p359-qroc-004","type":"QROC","rank":"B","objective":"p359-obj-03","tags":["pièges","biologie"],"difficulty":2,"question":"Chez un patient en détresse respiratoire aiguë, la gazométrie montre une hypocapnie marquée avec une PaO2 « normale ». Que traduit le plus souvent cette association ?","answer":"Une hypoxémie profonde masquée par l'hyperventilation","accept":["hypoxémie profonde masquée","hypoxémie masquée par l'hyperventilation","hypoxémie profonde masquée par l'hyperventilation secondaire","hypoxémie masquée"],"keywords":["hypox","masqu"],"explanation":"Les signes de détresse peuvent précéder une insuffisance respiratoire aiguë gazométrique : la gazométrie est alors faussement rassurante. Il faut la renouveler précocement si les signes persistent, penser aux hypoxies tissulaires sans hypoxémie et doser le lactate artériel.","src":"p. 317"},{"id":"p359-qroc-005","type":"QROC","rank":"A","objective":"p359-obj-04","tags":["clinique","définition"],"difficulty":1,"question":"Quelle fréquence respiratoire définit la tachypnée de l'adulte au cours d'une détresse respiratoire aiguë ?","answer":"Plus de 25 par minute","accept":["> 25/min","25/min","supérieure à 25","25 par minute","25"],"keywords":["25"],"explanation":"La tachypnée (FR > 25/min chez l'adulte) est un signe de lutte ; elle peut s'associer à une baisse du volume courant.","src":"p. 318"},{"id":"p359-qroc-006","type":"QROC","rank":"A","objective":"p359-obj-11","tags":["clinique","urgence"],"difficulty":2,"question":"Dans une détresse respiratoire aiguë, que traduisent une bradypnée ou des irrégularités respiratoires ?","answer":"Une défaillance neurologique (arrêt respiratoire imminent)","accept":["défaillance neurologique","arrêt respiratoire imminent","atteinte neurologique","défaillance neurologique plus que respiratoire"],"keywords":["neurolog"],"explanation":"Ce sont des signes d'extrême gravité, plus neurologiques que respiratoires : ils annoncent un arrêt respiratoire imminent.","src":"p. 318"},{"id":"p359-qroc-007","type":"QROC","rank":"A","objective":"p359-obj-04","tags":["clinique"],"difficulty":1,"question":"Quel bruit anormal témoigne d'une obstruction des voies aériennes supérieures (larynx ou trachée cervicale) ?","answer":"Le stridor","accept":["stridor","cornage","le cornage"],"keywords":["stridor"],"explanation":"Le stridor, bruit inspiratoire que l'on appelle aussi cornage, fait partie des signes de lutte et signe une obstruction haute.","src":"p. 318, 325"},{"id":"p359-qroc-008","type":"QROC","rank":"A","objective":"p359-obj-11","tags":["clinique","urgence"],"difficulty":1,"question":"Comment définit-on la respiration abdominale paradoxale ?","answer":"Recul de la paroi abdominale à l'inspiration","accept":["recul de la paroi abdominale antérieure à l'inspiration","l'abdomen recule à l'inspiration","dépression abdominale à l'inspiration","la paroi abdominale se creuse à l'inspiration"],"keywords":["recul","inspiration"],"explanation":"Au lieu de se bomber à l'inspiration, la paroi abdominale antérieure rentre : le diaphragme ne participe plus à la ventilation. C'est un signe de faillite de la pompe musculaire ventilatoire.","src":"p. 318"},{"id":"p359-qroc-009","type":"QROC","rank":"A","objective":"p359-obj-11","tags":["clinique","pièges"],"difficulty":1,"question":"Quelle position est proscrite chez un patient qui présente une respiration abdominale paradoxale ?","answer":"Le décubitus dorsal","accept":["décubitus dorsal","décubitus","allongé sur le dos","à plat dos"],"keywords":["decubitus"],"explanation":"La respiration abdominale paradoxale s'accompagne d'une orthopnée et elle est aggravée par le décubitus dorsal.","src":"p. 318"},{"id":"p359-qroc-010","type":"QROC","rank":"A","objective":"p359-obj-12","tags":["urgence","traitement"],"difficulty":1,"question":"Que doit faire discuter la découverte d'une respiration abdominale paradoxale chez un patient en détresse respiratoire ?","answer":"Une assistance ventilatoire","accept":["assistance ventilatoire","ventilation assistée","ventilation mécanique","mise en route d'une assistance ventilatoire"],"keywords":["ventilat"],"explanation":"Signe de faillite de la pompe musculaire, il fait craindre une défaillance à court terme : on discute une assistance ventilatoire, et au minimum l'admission dans une structure où elle peut être mise en place sans délai.","src":"p. 318"},{"id":"p359-qroc-011","type":"QROC","rank":"A","objective":"p359-obj-11","tags":["clinique","physiopathologie"],"difficulty":1,"question":"Au-delà de quelle concentration d'hémoglobine réduite (désoxygénée) dans le sang capillaire la cyanose apparaît-elle ?","answer":"5 g/dL","accept":["5 g/100 mL","5 g/dl","plus de 5 g/dL","> 5 g/dL","5"],"keywords":["5"],"explanation":"La cyanose traduit une hypoxémie profonde. Une anémie profonde la rend absente ou très tardive ; une polyglobulie la rend fréquente mais moins spécifique.","src":"p. 319"},{"id":"p359-qroc-012","type":"QROC","rank":"A","objective":"p359-obj-11","tags":["clinique","pièges"],"difficulty":2,"question":"Que dire de la sensibilité et de la spécificité de la cyanose pour détecter une hypoxémie profonde ?","answer":"Peu sensible mais spécifique","accept":["peu sensible, spécifique","peu sensible et spécifique","spécifique mais peu sensible","spécifique, peu sensible","faible sensibilité, bonne spécificité"],"keywords":["peu sensible","specifique"],"explanation":"Signe peu sensible mais spécifique : sa constatation impose une oxygénothérapie immédiate. La SpO2 alerte plus précocement.","src":"p. 319"},{"id":"p359-qroc-013","type":"QROC","rank":"A","objective":"p359-obj-11","tags":["clinique"],"difficulty":1,"question":"Chez un patient mélanoderme, quelle zone examine-t-on pour apprécier une coloration bleutée évoquant la cyanose ?","answer":"La langue","accept":["langue","la langue"],"keywords":["langue"],"explanation":"La cyanose cutanée est prise en défaut chez les sujets mélanodermes : on apprécie alors la coloration de la langue.","src":"p. 319"},{"id":"p359-qroc-014","type":"QROC","rank":"A","objective":"p359-obj-11","tags":["urgence","traitement"],"difficulty":1,"question":"Quel seuil de SpO2 impose une oxygénothérapie immédiate ?","answer":"SpO2 < 90 %","accept":["< 90 %","90 %","90%","inférieure à 90 %","90"],"keywords":["90"],"explanation":"La SpO2 alerte plus précocement que la cyanose : une valeur inférieure à 90 % impose, comme la cyanose, une oxygénothérapie immédiate.","src":"p. 319"},{"id":"p359-qroc-015","type":"QROC","rank":"A","objective":"p359-obj-11","tags":["clinique"],"difficulty":2,"question":"Quel signe neurologique, défini comme une abolition transitoire du tonus de posture, évoque une hypercapnie d'installation assez rapide ?","answer":"L'astérixis (flapping tremor)","accept":["astérixis","asterixis","flapping tremor","flapping","tremblement de type flapping"],"keywords":["asterixis"],"explanation":"Ce signe n'est pas spécifique : on le rencontre aussi dans d'autres affections, par exemple l'encéphalopathie hépatique.","src":"p. 319"},{"id":"p359-qroc-016","type":"QROC","rank":"B","objective":"p359-obj-14","tags":["urgence","traitement"],"difficulty":1,"question":"Dans un contexte de détresse respiratoire, quel score de Glasgow constitue une indication d'intubation trachéale ?","answer":"Glasgow < 9","accept":["< 9","inférieur à 9","moins de 9","9","≤ 8","8"],"keywords":["9"],"explanation":"Une altération marquée de la vigilance (Glasgow < 9) justifie l'intubation pour protéger les voies aériennes d'une inhalation d'origine digestive.","src":"p. 319"},{"id":"p359-qroc-017","type":"QROC","rank":"A","objective":"p359-obj-11","tags":["clinique","urgence"],"difficulty":2,"question":"Quels sont les trois signes cliniques d'insuffisance cardiaque droite aiguë (cœur pulmonaire aigu) recherchés devant une détresse respiratoire ?","answer":"Turgescence jugulaire, reflux hépato-jugulaire, hépatomégalie douloureuse","accept":["turgescence jugulaire, reflux hépatojugulaire, hépatomégalie douloureuse","turgescence jugulaire, RHJ, hépatomégalie douloureuse","TJ, RHJ, hépatomégalie"],"keywords":["turgescence","reflux","hepatomegalie"],"explanation":"Ces signes évoquent une embolie pulmonaire massive, un pneumothorax compressif, un asthme aigu grave ou une tamponnade.","src":"p. 319"},{"id":"p359-qroc-018","type":"QROC","rank":"B","objective":"p359-obj-11","tags":["clinique","étiologie"],"difficulty":2,"question":"Un pouls paradoxal (baisse de la pression artérielle systolique à l'inspiration) évoque quelles deux étiologies de détresse respiratoire ?","answer":"Asthme aigu grave et tamponnade cardiaque","accept":["asthme aigu grave, tamponnade","tamponnade et asthme aigu grave","AAG et tamponnade","asthme grave et tamponnade"],"keywords":["asthme","tamponnade"],"explanation":"Le pouls paradoxal est difficile à rechercher : on l'observe idéalement avec une mesure invasive de la pression artérielle (cathéter artériel).","src":"p. 319"},{"id":"p359-qroc-019","type":"QROC","rank":"A","objective":"p359-obj-11","tags":["clinique","urgence"],"difficulty":1,"question":"Quel seuil de pression artérielle systolique définit l'hypotension d'un état de choc compliquant une détresse respiratoire ?","answer":"PAS < 90 mmHg (ou chute de plus de 30 mmHg)","accept":["< 90 mmHg","90 mmHg","PAS < 90","inférieure à 90 mmHg","chute de plus de 30 mmHg","90"],"keywords":["90"],"explanation":"L'état de choc associe aussi peau froide, marbrures, temps de recoloration allongé, tachycardie > 120/min, confusion et oligurie.","src":"p. 320"},{"id":"p359-qroc-020","type":"QROC","rank":"A","objective":"p359-obj-11","tags":["clinique","pièges"],"difficulty":2,"question":"Quelle anomalie de la pression artérielle doit faire rechercher une hypercapnie chez un patient en détresse respiratoire ?","answer":"L'hypertension artérielle","accept":["HTA","hypertension","une HTA","hypertension artérielle"],"keywords":["hypertension"],"explanation":"L'hypercapnie donne aussi des céphalées et une hyperhémie conjonctivale (effet vasodilatateur du CO2), ainsi que tremblements, sueurs et tachycardie (réaction adrénergique).","src":"p. 320"},{"id":"p359-qroc-021","type":"QROC","rank":"A","objective":"p359-obj-13","tags":["traitement","urgence"],"difficulty":1,"question":"Quelle valeur de SpO2 vise l'oxygénothérapie initiale d'une détresse respiratoire aiguë avec hypoxémie profonde ?","answer":"SpO2 entre 88 et 92 %","accept":["88-92 %","88-92","entre 88 et 92","88 à 92 %","88 et 92"],"keywords":["88","92"],"explanation":"Cette cible doit être atteinte très rapidement pour prévenir l'arrêt cardio-respiratoire hypoxique ; le débit est ensuite adapté à l'évolution clinique et à la SpO2.","src":"p. 320"},{"id":"p359-qroc-022","type":"QROC","rank":"A","objective":"p359-obj-13","tags":["traitement","pièges"],"difficulty":2,"question":"Chez un patient BPCO en détresse respiratoire aiguë avec hypoxémie profonde, comment débute-t-on l'oxygénothérapie (niveau de débit) ?","answer":"À haut débit, puis débit adapté","accept":["haut débit","à haut débit","d'emblée à haut débit","haut débit puis adaptation"],"keywords":["haut"],"explanation":"Même en cas de BPCO ou d'insuffisance respiratoire chronique, l'oxygène est débuté à haut débit, puis le débit est rapidement adapté ; les gaz du sang sous oxygène vérifient l'absence d'hypercapnie.","src":"p. 320-321"},{"id":"p359-qroc-023","type":"QROC","rank":"A","objective":"p359-obj-13","tags":["traitement"],"difficulty":2,"question":"À partir de quel débit d'oxygène (en L/min) envisage-t-on des canules nasales à haut débit, dont le mélange est réchauffé et humidifié ?","answer":"Au-delà de 15 L/min","accept":["15 L/min","> 15 L/min","plus de 15 L/min","15"],"keywords":["15"],"explanation":"Un masque simple sert pour des débits de 5 à 10 L/min et un masque à haute concentration « avec réserve » pour des débits > 8 L/min ; les canules nasales à haut débit (10 à 50 L/min) viennent ensuite.","src":"p. 321"},{"id":"p359-qroc-024","type":"QROC","rank":"A","objective":"p359-obj-13","tags":["traitement","biologie"],"difficulty":2,"question":"Quel examen faut-il contrôler sous oxygène, surtout chez l'insuffisant respiratoire chronique, pour vérifier l'efficacité du dispositif et l'absence d'hypercapnie ?","answer":"Les gaz du sang artériel","accept":["gazométrie artérielle","gaz du sang","gazométrie","GDS"],"keywords":["gaz"],"explanation":"Chez l'insuffisant respiratoire chronique, corriger le stimulus hypoxémique peut inhiber les centres respiratoires et provoquer une hypercapnie.","src":"p. 321"},{"id":"p359-qroc-025","type":"QROC","rank":"B","objective":"p359-obj-14","tags":["traitement"],"difficulty":1,"question":"Quelles sont les deux situations pour lesquelles la ventilation non invasive est essentiellement indiquée en détresse respiratoire aiguë ?","answer":"Exacerbation de BPCO en acidose respiratoire (pH < 7,35) et OAP cardiogénique","accept":["exacerbation de BPCO et OAP cardiogénique","BPCO acidosique et OAP","BPCO en acidose respiratoire et OAP","bpco et oap","exacerbation de BPCO et œdème pulmonaire cardiogénique"],"keywords":["bpco","cardiogen"],"explanation":"La VNI est réservée aux défaillances respiratoires isolées chez des patients coopérants. Elle réduit la morbi-mortalité et les infections nosocomiales respiratoires, car le verrou glottique est préservé.","src":"p. 322"},{"id":"p359-qroc-026","type":"QROC","rank":"B","objective":"p359-obj-14","tags":["traitement","urgence"],"difficulty":2,"question":"Quelle ventilation faut-il choisir d'emblée lorsque la défaillance respiratoire n'est pas isolée (troubles de conscience, choc, polytraumatisme…) ?","answer":"La ventilation invasive (intubation)","accept":["ventilation invasive","intubation","intubation trachéale","ventilation mécanique invasive"],"keywords":["intubation"],"explanation":"La ventilation invasive est aussi la solution de 2e intention en cas d'échec de la VNI. Son interface est une sonde d'intubation trachéale, alors que la VNI passe par un masque.","src":"p. 322"},{"id":"p359-qroc-027","type":"QROC","rank":"A","objective":"p359-obj-10","tags":["paraclinique","urgence"],"difficulty":1,"question":"Quels sont les trois examens complémentaires à mettre en route immédiatement devant une détresse respiratoire aiguë ?","answer":"Radiographie thoracique, gazométrie artérielle avec lactate, ECG","accept":["radio thorax, gazométrie, ECG","radiographie du thorax, gaz du sang et lactate, ECG","radio de thorax, GDS, ECG"],"keywords":["radio","gaz","ecg"],"explanation":"La radiographie se fait au lit dès que le traitement symptomatique est débuté. NFS-plaquettes et ionogramme sanguin-urée-créatinine sont aussi systématiques ; le reste dépend des hypothèses diagnostiques.","src":"p. 323"},{"id":"p359-qroc-028","type":"QROC","rank":"A","objective":"p359-obj-10","tags":["ECG","diagnostic"],"difficulty":2,"question":"Un ECG normal est un argument important contre quel diagnostic chez un patient en détresse respiratoire ?","answer":"L'œdème aigu pulmonaire cardiogénique (OAP)","accept":["OAP","OAP cardiogénique","œdème aigu du poumon cardiogénique","œdème pulmonaire cardiogénique","œdème aigu pulmonaire"],"keywords":["cardiogen"],"explanation":"Un ECG normal a une bonne valeur prédictive négative pour l'OAP cardiogénique. L'ECG cherche aussi une arythmie, une ischémie, des signes d'embolie pulmonaire ou de tamponnade.","src":"p. 323, 326"},{"id":"p359-qroc-029","type":"QROC","rank":"A","objective":"p359-obj-10","tags":["biologie"],"difficulty":1,"question":"Quel seuil de BNP permet d'exclure une dyspnée aiguë d'origine cardiaque ?","answer":"BNP < 100 pg/mL","accept":["< 100 pg/mL","100 pg/mL","inférieur à 100 pg/mL","100"],"keywords":["100"],"explanation":"Bonne valeur prédictive négative. En revanche un BNP élevé n'est pas spécifique de l'OAP : il s'élève dès qu'un ventricule (gauche ou droit) est dilaté ou fait face à une post-charge accrue, par exemple dans l'embolie pulmonaire aiguë ou l'exacerbation de BPCO.","src":"p. 323"},{"id":"p359-qroc-030","type":"QROC","rank":"A","objective":"p359-obj-10","tags":["imagerie","diagnostic"],"difficulty":1,"question":"Quel examen d'imagerie affirme le diagnostic d'embolie pulmonaire devant une détresse respiratoire sans anomalie radiologique ?","answer":"L'angioscanner thoracique","accept":["angioscanner","angio-scanner thoracique","angio-scanner","angioscanner pulmonaire","angio-TDM","angioscan"],"keywords":["scanner"],"explanation":"Il est demandé en cas de forte probabilité d'embolie pulmonaire ou de D-dimères élevés ; les D-dimères sont réservés aux probabilités faible ou intermédiaire. La radiographie est le plus souvent normale.","src":"p. 323, 327"},{"id":"p359-qroc-031","type":"QROC","rank":"A","objective":"p359-obj-09","tags":["étiologie","urgence"],"difficulty":1,"question":"Quelle est la première étape du diagnostic étiologique d'une détresse respiratoire aiguë de l'adulte ?","answer":"Éliminer une obstruction des voies aériennes supérieures (corps étranger)","accept":["obstruction des VAS","obstruction des voies aériennes supérieures","éliminer un corps étranger","corps étranger des voies aériennes supérieures","corps étranger"],"keywords":["obstruction"],"explanation":"Cette étape passe avant les autres, car l'urgence est extrême et la prise en charge diffère radicalement de celle des autres causes. Viennent ensuite la radiographie thoracique et la gazométrie artérielle.","src":"p. 324-325"},{"id":"p359-qroc-032","type":"QROC","rank":"A","objective":"p359-obj-15","tags":["clinique","urgence"],"difficulty":1,"question":"Un patient paniqué, portant les mains à son cou et gesticulant sans émettre aucun son : quel diagnostic évoquer en urgence ?","answer":"Une obstruction (totale) des voies aériennes supérieures","accept":["obstruction des VAS","obstruction des voies aériennes supérieures","obstruction totale des voies aériennes","inhalation de corps étranger","corps étranger"],"keywords":["obstruction"],"explanation":"Le diagnostic est avant tout clinique : bradypnée inspiratoire avec temps inspiratoire allongé, dysphonie (aphonie et absence de flux si l'obstruction est totale), cornage ou stridor.","src":"p. 325"},{"id":"p359-qroc-033","type":"QROC","rank":"A","objective":"p359-obj-09","tags":["étiologie","diagnostic"],"difficulty":1,"question":"Devant une détresse respiratoire aiguë avec anomalies radiologiques, quels sont les trois diagnostics à évoquer en priorité ?","answer":"Pneumonie, OAP cardiogénique, pneumothorax sous tension","accept":["pneumonie, OAP, pneumothorax","pneumopathie, OAP, pneumothorax","pneumonie, OAP cardiogénique, PNO sous tension","pneumonie, œdème aigu pulmonaire, pneumothorax"],"keywords":["pneumonie","oap","pneumothorax"],"explanation":"Pneumonie à suspecter d'abord en cas de fièvre ; OAP cardiogénique chez un sujet âgé ou cardiaque, sans fièvre ; pneumothorax sous tension surtout si maladie respiratoire chronique (asymétrie auscultatoire, douleur latéro-thoracique).","src":"p. 325"},{"id":"p359-qroc-034","type":"QROC","rank":"A","objective":"p359-obj-09","tags":["clinique","étiologie"],"difficulty":1,"question":"Quel élément clinique fait suspecter une pneumonie en première intention devant une détresse respiratoire aiguë avec anomalies radiologiques ?","answer":"La fièvre","accept":["fièvre","fièvre élevée","fièvre et frissons"],"keywords":["fievre"],"explanation":"L'OAP cardiogénique se rencontre plutôt sans fièvre, chez un sujet âgé ou avec une cardiopathie.","src":"p. 325"},{"id":"p359-qroc-035","type":"QROC","rank":"A","objective":"p359-obj-05","tags":["clinique","diagnostic"],"difficulty":1,"question":"Quel type d'expectoration oriente vers un OAP cardiogénique plutôt que vers une pneumonie ?","answer":"Expectoration mousseuse, parfois rosée","accept":["mousseuse","mousseuses","expectorations mousseuses","mousseuse rosée","mousseuses, parfois rosées"],"keywords":["mousseu"],"explanation":"L'OAP associe expectorations mousseuses, orthopnée, HTA, tachycardie et râles crépitants bilatéraux prédominant aux bases ; la pneumonie associe fièvre élevée, frissons et foyer de râles crépitants.","src":"p. 326"},{"id":"p359-qroc-036","type":"QROC","rank":"A","objective":"p359-obj-01","tags":["imagerie"],"difficulty":1,"question":"Quel aspect radiographique évoque un œdème aigu pulmonaire cardiogénique ?","answer":"Opacités alvéolaires bilatérales, diffuses, péri-hilaires","accept":["opacités alvéolaires bilatérales diffuses péri-hilaires","opacités bilatérales péri-hilaires","opacités alvéolaires bilatérales et diffuses","images alvéolaires bilatérales péri-hilaires"],"keywords":["bilateral","hilaire"],"explanation":"À l'inverse, les opacités alvéolaires de la pneumonie sont le plus souvent systématisées.","src":"p. 326"},{"id":"p359-qroc-037","type":"QROC","rank":"A","objective":"p359-obj-02","tags":["imagerie"],"difficulty":1,"question":"Quel aspect radiographique est le plus souvent observé dans une pneumonie ?","answer":"Des opacités alvéolaires systématisées","accept":["opacités alvéolaires systématisées","opacité alvéolaire systématisée","foyer alvéolaire systématisé","opacités systématisées"],"keywords":["systematis"],"explanation":"Le tableau comporte aussi un syndrome inflammatoire, une hyperleucocytose et un foyer de râles crépitants ; l'OAP donne au contraire des opacités bilatérales, diffuses, péri-hilaires.","src":"p. 326"},{"id":"p359-qroc-038","type":"QROC","rank":"A","objective":"p359-obj-09","tags":["biologie","étiologie"],"difficulty":2,"question":"Quels éléments gazométriques orientent vers la décompensation d'une maladie respiratoire chronique plutôt que vers une maladie aiguë « de novo » ?","answer":"Hypercapnie avec pH anormal et bicarbonates > 30 mmol/L","accept":["hypercapnie et bicarbonates élevés","hypercapnie, bicarbonates > 30 mmol/L","PaCO2 ≥ 45 mmHg et HCO3- > 30 mmol/L","hypercapnie et hco3 > 30"],"keywords":["hypercapnie","bicarbonate"],"explanation":"L'élévation des bicarbonates (> 30 mmol/L) témoigne d'une hypercapnie chronique ; l'hypercapnie est ici définie par une PaCO2 ≥ 45 mmHg avec un pH anormal.","src":"p. 326"},{"id":"p359-qroc-039","type":"QROC","rank":"A","objective":"p359-obj-09","tags":["étiologie"],"difficulty":1,"question":"Une détresse respiratoire aiguë sans anomalie radiologique est orientée par la gazométrie vers une maladie aiguë « de novo » : quelles sont les trois étiologies à évoquer ?","answer":"Embolie pulmonaire, pneumothorax, exacerbation d'asthme","accept":["EP, pneumothorax, asthme","EP, PNO, asthme","embolie pulmonaire, PNO, crise d'asthme"],"keywords":["embolie","pneumothorax","asthme"],"explanation":"Le diagnostic d'embolie pulmonaire est affirmé par l'angioscanner. Le pneumothorax survient volontiers chez un sujet longiligne, tabagique ou porteur de lésions emphysémateuses ; l'asthme peut être précédé d'une perte de contrôle.","src":"p. 327"},{"id":"p359-qroc-040","type":"QROC","rank":"A","objective":"p359-obj-05","tags":["clinique"],"difficulty":2,"question":"Quels signes à l'examen thoracique (palpation, auscultation, percussion) évoquent un pneumothorax ?","answer":"Abolition des vibrations vocales et du murmure vésiculaire, tympanisme","accept":["abolition des vibrations vocales, abolition du murmure vésiculaire, tympanisme","vibrations vocales abolies, murmure vésiculaire aboli, tympanisme","abolition VV et MV, tympanisme"],"keywords":["vibration","murmure","tympanisme"],"explanation":"Le pneumothorax débute brutalement, avec une douleur latéro-thoracique augmentée à l'inspiration et une toux non productive ; la radiographie montre une hyperclarté délimitée par une ligne pleurale.","src":"p. 327"},{"id":"p359-qroc-041","type":"QROC","rank":"A","objective":"p359-obj-05","tags":["imagerie","diagnostic"],"difficulty":2,"question":"Quel est l'aspect le plus fréquent de la radiographie thoracique dans l'embolie pulmonaire ?","answer":"Une radiographie normale","accept":["normale","radiographie thoracique normale","radio normale"],"keywords":["normal"],"explanation":"Des signes sont possibles (ascension de coupole, atélectasie en bande, opacité périphérique d'infarctus, petit épanchement pleural), mais la radiographie reste le plus souvent normale.","src":"p. 327"},{"id":"p359-qroc-042","type":"QROC","rank":"B","objective":"p359-obj-08","tags":["définition","physiopathologie"],"difficulty":2,"question":"Un patient en SDRA a un rapport PaO2/FiO2 à 150 mmHg sous PEP de 8 cmH2O. Quel est le niveau de sévérité ?","answer":"SDRA modéré","accept":["modéré","sdra modéré"],"keywords":["modere"],"explanation":"Léger : PaO2/FiO2 de 200 à 300 mmHg ; modéré : de 100 à 200 mmHg ; sévère : ≤ 100 mmHg, toujours avec une PEP (ou une CPAP) ≥ 5 cmH2O.","src":"p. 328"},{"id":"p359-qroc-043","type":"QROC","rank":"B","objective":"p359-obj-08","tags":["physiopathologie"],"difficulty":2,"question":"Quel mécanisme lésionnel distingue le SDRA de l'œdème pulmonaire cardiogénique ?","answer":"Hyperperméabilité de la barrière alvéolo-endothéliale (œdème lésionnel)","accept":["augmentation de la perméabilité alvéolo-endothéliale","augmentation de la perméabilité de la barrière alvéolo-endothéliale","œdème lésionnel","exsudation intra-alvéolaire","perméabilité alvéolo-capillaire"],"keywords":["permeabilit"],"explanation":"Dans le SDRA, la pression hydrostatique microvasculaire n'est pas augmentée : l'œdème vient d'une exsudation intra-alvéolaire par hyperperméabilité, avec dommage alvéolaire diffus (alors que l'OAP relève d'une transsudation intra-alvéolaire).","src":"p. 328"},{"id":"p359-qroc-044","type":"QROC","rank":"B","objective":"p359-obj-08","tags":["étiologie"],"difficulty":1,"question":"Dans le tableau des étiologies du SDRA, quelle agression endogène est notée comme très fréquente (+++) ?","answer":"Le sepsis sévère","accept":["sepsis","sepsis grave","tout sepsis sévère"],"keywords":["sepsis"],"explanation":"Tout sepsis sévère, quels que soient l'agent pathogène et la porte d'entrée, peut entraîner un SDRA. Autres causes endogènes : pancréatite aiguë, embolie amniotique, circulation extracorporelle, transfusions massives, polytraumatisme, brûlures étendues.","src":"p. 329"},{"id":"p359-qru-101","type":"QRU","rank":"A","objective":"p359-obj-03","tags":["définition"],"difficulty":1,"stem":"Parmi les propositions suivantes, laquelle définit l'insuffisance respiratoire aiguë (IRA) ?","options":[{"t":"Ensemble des signes cliniques directs et indirects qui témoignent de la gravité d'une affection respiratoire","ok":false,"why":"C'est la définition de la détresse respiratoire (versant clinique), pas de l'IRA gazométrique."},{"t":"Œdème lésionnel du poumon, d'évolution aiguë, avec opacités alvéolaires bilatérales et diffuses","ok":false,"why":"Cette description correspond au SDRA, une des étiologies de détresse respiratoire."},{"t":"Altération aiguë de l'hématose : PaO2 < 60 mmHg avec modification du pH, notamment acidose respiratoire","ok":true,"why":"C'est la définition gazométrique : hypoxémie profonde associée à une modification du pH témoignant du caractère aigu."},{"t":"Toute hypoxie tissulaire, y compris sans hypoxémie : anémie, intoxication au monoxyde de carbone, choc","ok":false,"why":"La définition gazométrique exclut justement les hypoxies tissulaires sans hypoxémie."},{"t":"Hypoxémie isolée (PaO2 < 60 mmHg) avec un pH normal, sans aucune modification de la PaCO2","ok":false,"why":"L'IRA associe l'hypoxémie profonde à une modification du pH ; l'hypoxémie seule ne suffit pas à la définir."}],"explanation":"La détresse respiratoire est un ensemble de signes cliniques de gravité ; l'IRA en est le versant gazométrique (altération aiguë de l'hématose).","trap":"Ne pas confondre détresse respiratoire (clinique), IRA (gazométrique) et SDRA (une étiologie).","src":"p. 317"},{"id":"p359-qru-102","type":"QRU","rank":"A","objective":"p359-obj-13","tags":["traitement","pièges"],"difficulty":2,"stem":"Un patient de 68 ans, BPCO connu, est en détresse respiratoire aiguë avec cyanose et une SpO2 à 78 % à l'air ambiant. Quelle est la conduite d'oxygénothérapie initiale ?","options":[{"t":"Débuter à faible débit, pour ne pas inhiber les centres respiratoires, quitte à tolérer une SpO2 basse","ok":false,"why":"Le chapitre demande un haut débit initial, y compris chez le BPCO : la correction de l'hypoxémie profonde prime."},{"t":"Retarder l'oxygène jusqu'au résultat des gaz du sang artériel, pour adapter le débit à la PaCO2","ok":false,"why":"Une cyanose ou une SpO2 < 90 % impose une oxygénothérapie immédiate, sans attendre la gazométrie."},{"t":"Viser d'emblée une SpO2 supérieure à 98 %, quel que soit le terrain respiratoire du patient","ok":false,"why":"La cible indiquée est une SpO2 entre 88 et 92 %."},{"t":"Débuter à haut débit, puis adapter rapidement le débit à la clinique et à la SpO2 mesurée","ok":true,"why":"Même chez un BPCO, l'hypoxémie profonde se corrige d'emblée à haut débit ; la cible est une SpO2 de 88 à 92 %."},{"t":"Réserver l'oxygène aux patients non BPCO et proposer d'emblée une ventilation mécanique aux BPCO","ok":false,"why":"L'oxygène est toujours administré en détresse respiratoire ; l'assistance ventilatoire n'est ajoutée que selon des indications précises."}],"explanation":"Oxygène toujours, haut débit d'emblée (BPCO compris), cible 88-92 %, puis contrôle des gaz du sang sous oxygène pour dépister une hypercapnie.","trap":"Le réflexe « BPCO = peu d'oxygène » est faux en détresse avec hypoxémie profonde.","src":"p. 319-321"},{"id":"p359-qru-103","type":"QRU","rank":"A","objective":"p359-obj-09","tags":["diagnostic","étiologie"],"difficulty":1,"stem":"Une femme de 79 ans, hypertendue et insuffisante cardiaque, présente une détresse respiratoire aiguë d'aggravation rapide, sans fièvre. Elle a une orthopnée, une expectoration mousseuse rosée et des râles crépitants bilatéraux prédominant aux bases. La radiographie montre des opacités alvéolaires bilatérales, diffuses, péri-hilaires. Quel est le diagnostic le plus probable ?","options":[{"t":"Pneumonie aiguë communautaire","ok":false,"why":"La pneumonie donne plutôt fièvre élevée, frissons, foyer de crépitants et opacités le plus souvent systématisées."},{"t":"Pneumothorax sous tension","ok":false,"why":"Il évoque une asymétrie auscultatoire, avec ou sans douleur latéro-thoracique, ce qui n'est pas le cas ici."},{"t":"Embolie pulmonaire massive","ok":false,"why":"L'embolie pulmonaire s'accompagne le plus souvent d'une radiographie normale."},{"t":"Œdème aigu pulmonaire cardiogénique","ok":true,"why":"Terrain cardiaque, absence de fièvre, orthopnée, expectoration mousseuse et opacités bilatérales péri-hilaires : tableau typique d'OAP."},{"t":"Syndrome de détresse respiratoire aiguë (SDRA)","ok":false,"why":"La définition du SDRA exige l'absence de défaillance cardiaque ou de surcharge volémique."}],"explanation":"Sujet âgé ou cardiaque, apyrétique, orthopnée, expectoration mousseuse, crépitants bilatéraux et opacités bilatérales péri-hilaires : OAP cardiogénique. Le BNP serait élevé et l'ECG n'est jamais normal dans ce cas.","src":"p. 325-326"},{"id":"p359-qru-104","type":"QRU","rank":"A","objective":"p359-obj-09","tags":["biologie","étiologie"],"difficulty":3,"stem":"Un patient de 70 ans est en détresse respiratoire aiguë. La radiographie thoracique ne montre aucune opacité. Gaz du sang : pH 7,28 ; PaCO2 62 mmHg ; bicarbonates 36 mmol/L. Quelle orientation ces résultats suggèrent-ils ?","options":[{"t":"Embolie pulmonaire, à confirmer par angioscanner","ok":false,"why":"L'embolie pulmonaire est une étiologie aiguë « de novo » ; l'élévation des bicarbonates oriente vers une hypercapnie chronique."},{"t":"Décompensation aiguë d'une maladie respiratoire chronique","ok":true,"why":"Hypercapnie avec pH anormal et bicarbonates > 30 mmol/L (témoin d'une hypercapnie chronique) : décompensation d'une pathologie chronique."},{"t":"Pneumothorax, à rechercher à l'auscultation et à la percussion","ok":false,"why":"C'est une étiologie « de novo » ; ce n'est pas l'orientation que donnent des bicarbonates élevés."},{"t":"Exacerbation d'asthme avec dyspnée expiratoire","ok":false,"why":"C'est une étiologie « de novo » ; ce n'est pas l'orientation que donnent des bicarbonates élevés."},{"t":"Obstruction des voies aériennes supérieures par un corps étranger","ok":false,"why":"Elle est recherchée en première étape sur la clinique (patient paniqué, stridor, aphonie), pas sur la gazométrie."}],"explanation":"En l'absence d'opacités, la gazométrie sépare les maladies aiguës « de novo » (embolie pulmonaire, pneumothorax, asthme) des décompensations de maladie chronique (hypercapnie, bicarbonates > 30 mmol/L).","src":"p. 326-327"},{"id":"p359-qru-105","type":"QRU","rank":"A","objective":"p359-obj-11","tags":["clinique","urgence"],"difficulty":2,"stem":"Chez un patient en détresse respiratoire aiguë, la paroi antérieure de l'abdomen recule à chaque inspiration. Que signifie ce signe ?","options":[{"t":"Une faillite de la pompe ventilatoire","ok":true,"why":"Le recul abdominal inspiratoire traduit l'absence de participation du diaphragme ; la ventilation est relayée par les muscles extra-diaphragmatiques, avec risque de défaillance à court terme."},{"t":"Un signe de lutte banal, sans valeur de gravité particulière","ok":false,"why":"Tout signe de faillite signe la gravité de la détresse ; ce n'est pas un signe de lutte banal."},{"t":"Une expiration abdominale active, évocatrice d'une pathologie obstructive","ok":false,"why":"C'est un phénomène différent (activation des muscles abdominaux à l'expiration) que le chapitre demande de ne pas confondre avec la respiration paradoxale."},{"t":"Un signe évocateur d'une hypercapnie","ok":false,"why":"Les signes évocateurs d'hypercapnie sont autres : céphalées, hyperhémie conjonctivale, tremblements, sueurs, HTA."},{"t":"Une obstruction des voies aériennes supérieures","ok":false,"why":"Celle-ci se manifeste par une bradypnée inspiratoire, un cornage ou stridor, une dysphonie ou aphonie."}],"explanation":"La respiration abdominale paradoxale oriente vers une assistance ventilatoire (ou au minimum un transfert vers une structure qui peut la mettre en place sans délai) ; le décubitus dorsal est proscrit.","src":"p. 318"},{"id":"p359-qru-106","type":"QRU","rank":"B","objective":"p359-obj-14","tags":["traitement","urgence"],"difficulty":3,"stem":"Un patient de 72 ans, BPCO, coopérant, est en détresse respiratoire aiguë isolée (sans trouble de conscience ni choc). Les gaz du sang montrent une hypercapnie avec un pH à 7,28. Quelle ventilation est indiquée ?","options":[{"t":"Ventilation invasive d'emblée, par intubation trachéale","ok":false,"why":"La ventilation invasive d'emblée est réservée aux défaillances non isolées (troubles de conscience, choc, polytraumatisme...) ; sinon c'est une solution de 2e intention."},{"t":"Oxygénothérapie à bas débit seule, sans assistance ventilatoire","ok":false,"why":"L'acidose respiratoire (pH < 7,35) fait partie des indications de ventilation mécanique."},{"t":"Aucune ventilation : une acidose respiratoire n'est pas une indication","ok":false,"why":"Hypercapnie avec pH < 7,35 figure parmi les indications pratiques de ventilation mécanique."},{"t":"Ventilation invasive systématique, la VNI étant contre-indiquée chez le BPCO","ok":false,"why":"La VNI est au contraire un support de l'exacerbation de BPCO en acidose respiratoire."},{"t":"Ventilation non invasive (VNI) par masque naso-buccal","ok":true,"why":"Exacerbation de BPCO en acidose respiratoire (pH < 7,35), défaillance respiratoire isolée, patient coopérant : indication principale de la VNI."}],"explanation":"VNI : exacerbation de BPCO en acidose respiratoire (pH < 7,35) et OAP cardiogénique, chez un patient coopérant avec défaillance isolée ; elle réduit la morbi-mortalité et les infections nosocomiales respiratoires.","src":"p. 322"},{"id":"p359-qru-107","type":"QRU","rank":"B","objective":"p359-obj-14","tags":["urgence","traitement"],"difficulty":2,"stem":"Un patient en détresse respiratoire aiguë avec hypercapnie est somnolent, peu réactif : score de Glasgow à 7. Quelle prise en charge ventilatoire est indiquée ?","options":[{"t":"Ventilation non invasive par masque, en première intention","ok":false,"why":"La VNI est réservée aux défaillances respiratoires isolées chez des patients coopérants ; les troubles de conscience imposent la ventilation invasive."},{"t":"Intubation trachéale puis ventilation mécanique invasive","ok":true,"why":"Glasgow < 9 dans une détresse respiratoire : indication d'intubation, notamment pour protéger les voies aériennes d'une inhalation d'origine digestive."},{"t":"Oxygénothérapie à haut débit seule, sans assistance ventilatoire","ok":false,"why":"Troubles de conscience et hypercapnie font partie des indications pratiques de ventilation mécanique."},{"t":"Traitement symptomatique seul : la vigilance n'est pas un critère de gravité","ok":false,"why":"L'altération marquée de la vigilance est un signe majeur de gravité."},{"t":"Abstention : une hypercapnie isolée ne justifie pas de ventilation mécanique","ok":false,"why":"L'acidose respiratoire (hypercapnie, pH < 7,35) et les troubles de conscience sont des indications de ventilation mécanique."}],"explanation":"Troubles de conscience (Glasgow < 9) : ventilation invasive d'emblée, car la défaillance respiratoire n'est pas isolée et il faut protéger les voies aériennes.","src":"p. 319, 322"},{"id":"p359-qru-108","type":"QRU","rank":"B","objective":"p359-obj-08","tags":["définition"],"difficulty":3,"stem":"Un patient en SDRA, ventilé avec une PEP à 8 cmH2O, a un rapport PaO2/FiO2 à 150 mmHg et une pression capillaire pulmonaire à 10 mmHg. Quel niveau de sévérité retenez-vous ?","options":[{"t":"OAP cardiogénique, le SDRA étant exclu par la pression capillaire","ok":false,"why":"La définition du SDRA exige une pression capillaire (PAPO) < 15 mmHg : à 10 mmHg, l'origine cardiaque est écartée."},{"t":"SDRA léger","ok":false,"why":"Le SDRA léger correspond à un rapport PaO2/FiO2 de 200 à 300 mmHg."},{"t":"SDRA sévère","ok":false,"why":"Le SDRA sévère correspond à un rapport ≤ 100 mmHg avec PEP ≥ 5 cmH2O."},{"t":"Pas de SDRA, car il faudrait un rapport PaO2/FiO2 < 100 mmHg","ok":false,"why":"Dès 200 à 300 mmHg sous PEP, on parle de SDRA léger ; la sévérité augmente quand le rapport diminue."},{"t":"SDRA modéré","ok":true,"why":"Un rapport entre 100 et 200 mmHg avec PEP ≥ 5 cmH2O correspond à un SDRA modéré."}],"explanation":"Léger : 200-300 mmHg ; modéré : 100-200 mmHg ; sévère : ≤ 100 mmHg, toujours avec une PEP (ou une CPAP) ≥ 5 cmH2O.","src":"p. 327-328"},{"id":"p359-qcm-101","type":"QRM","rank":"A","objective":"p359-obj-11","tags":["clinique"],"difficulty":1,"stem":"Parmi les signes suivants, lequel témoigne d'une faillite (et non d'une simple lutte) au cours d'une détresse respiratoire aiguë ?","options":[{"t":"Tirage sus-claviculaire et intercostal","ok":false,"why":"Le tirage traduit le recrutement des muscles inspiratoires extra-diaphragmatiques : signe de lutte."},{"t":"Tachypnée à 32/min avec polypnée superficielle","ok":false,"why":"La tachypnée (> 25/min) est un signe de lutte."},{"t":"Respiration abdominale paradoxale","ok":true,"why":"Signe de faillite de la pompe ventilatoire (absence de participation du diaphragme)."},{"t":"Expiration abdominale active (contraction des muscles abdominaux)","ok":false,"why":"Elle traduit le recrutement des muscles expiratoires : signe de lutte."},{"t":"Stridor inspiratoire, bruit de la voie aérienne haute","ok":false,"why":"Le stridor, signe d'obstruction des voies aériennes supérieures, est classé parmi les signes de lutte."}],"explanation":"Signes de lutte : tachypnée, recrutement musculaire (tirage, expiration abdominale active), stridor. Signes de faillite : respiration abdominale paradoxale, cyanose, signes neurologiques et hémodynamiques. Tout signe de faillite signe la gravité.","src":"p. 317-319"},{"id":"p359-qcm-102","type":"QRM","rank":"A","objective":"p359-obj-11","tags":["clinique","pièges"],"difficulty":2,"stem":"Concernant la cyanose au cours d'une détresse respiratoire aiguë, quelles propositions sont exactes ?","options":[{"t":"Chez le sujet mélanoderme, la peau reste l'endroit le plus fiable pour la reconnaître","ok":false,"why":"Elle est prise en défaut chez les sujets mélanodermes : on apprécie la coloration de la langue."},{"t":"Elle apparaît quand l'hémoglobine réduite dépasse 5 g/dL de sang capillaire","ok":true,"why":"C'est le seuil d'apparition de la cyanose, qui traduit une hypoxémie profonde."},{"t":"En cas de polyglobulie, la cyanose est plus rare mais plus spécifique","ok":false,"why":"En cas de polyglobulie, la cyanose est fréquente mais moins spécifique."},{"t":"Peu sensible mais spécifique, elle impose une oxygénothérapie immédiate","ok":true,"why":"Sa constatation impose l'oxygène sans attendre."},{"t":"Une anémie profonde peut la rendre absente ou très tardive","ok":true,"why":"Avec peu d'hémoglobine, le seuil de 5 g/dL d'hémoglobine réduite est atteint tard ou jamais."}],"explanation":"Pour une hémoglobine à 14 g/dL, la cyanose correspond à une SpO2 d'environ 80 % (PaO2 de 45 à 50 mmHg). La SpO2 alerte plus tôt : < 90 % impose aussi l'oxygénothérapie.","src":"p. 319"},{"id":"p359-qcm-103","type":"QRM","rank":"A","objective":"p359-obj-11","tags":["clinique"],"difficulty":2,"stem":"Parmi les signes suivants, lequel évoque une hypercapnie chez un patient en détresse respiratoire aiguë ?","options":[{"t":"Hypotension artérielle avec marbrures","ok":false,"why":"C'est une hypertension artérielle qui doit faire rechercher une hypercapnie ; l'hypotension avec marbrures est un signe de choc."},{"t":"Cyanose de la langue","ok":false,"why":"La cyanose traduit une hypoxémie profonde (faillite de l'oxygénation), non une hypercapnie."},{"t":"Tirage sus-claviculaire et intercostal","ok":false,"why":"C'est un signe de lutte (recrutement des muscles inspiratoires), pas un signe d'hypercapnie."},{"t":"Stridor inspiratoire avec dysphonie","ok":false,"why":"Ce sont des signes d'obstruction des voies aériennes supérieures."},{"t":"Hypervascularisation des conjonctives","ok":true,"why":"L'effet vasodilatateur du CO2 provoque céphalées et hyperhémie des conjonctives."}],"explanation":"Hypercapnie : céphalées, astérixis, somnolence puis troubles francs de conscience (carbonarcose), hyperhémie conjonctivale, et réaction adrénergique (tremblements, sueurs, tachycardie, HTA).","src":"p. 319-320"},{"id":"p359-qcm-104","type":"QRM","rank":"A","objective":"p359-obj-11","tags":["clinique","urgence"],"difficulty":2,"stem":"Quels signes témoignent d'une insuffisance circulatoire (état de choc) chez un patient en détresse respiratoire aiguë ?","options":[{"t":"Hypertension artérielle, qui oriente vers une hypoperfusion tissulaire","ok":false,"why":"L'hypertension doit faire rechercher une hypercapnie ; elle ne traduit pas un choc."},{"t":"Pression artérielle systolique < 90 mmHg","ok":true,"why":"Hypotension : PAS < 90 mmHg ou chute de plus de 30 mmHg par rapport à la pression habituelle."},{"t":"Peau chaude, sans marbrures, avec temps de recoloration raccourci","ok":false,"why":"Le choc donne une peau froide, des marbrures et un temps de recoloration allongé."},{"t":"Bradycardie, de règle dans l'insuffisance circulatoire","ok":false,"why":"Le choc s'accompagne d'une tachycardie supérieure à 120/min."},{"t":"Oligurie témoignant de l'hypoperfusion tissulaire","ok":true,"why":"Elle fait partie des signes d'hypoperfusion tissulaire."}],"explanation":"Le choc est une hypoperfusion tissulaire avec hypoxie de l'ensemble des organes : hypotension, peau froide, marbrures, tachycardie > 120/min, confusion ou altération de la vigilance, oligurie.","src":"p. 320"},{"id":"p359-qcm-105","type":"QRM","rank":"A","objective":"p359-obj-13","tags":["traitement","pièges"],"difficulty":2,"stem":"Concernant l'oxygénothérapie initiale d'une détresse respiratoire aiguë, quelles propositions sont exactes ?","options":[{"t":"Au-delà de 15 L/min, on peut recourir à des canules nasales à haut débit","ok":true,"why":"Le mélange gazeux de ces canules (10 à 50 L/min) est réchauffé et humidifié."},{"t":"Un masque simple suffit pour les débits supérieurs à 15 L/min","ok":false,"why":"Au-delà de 15 L/min, on envisage plutôt des canules nasales à haut débit."},{"t":"Une SpO2 de 99 % doit être recherchée dès les premières minutes","ok":false,"why":"La cible est comprise entre 88 et 92 %."},{"t":"La cible est une SpO2 entre 88 et 92 %","ok":true,"why":"Elle doit être atteinte très rapidement pour prévenir l'arrêt cardio-respiratoire hypoxique."},{"t":"Les gaz du sang sous oxygène vérifient l'absence d'hypercapnie","ok":true,"why":"Contrôle surtout utile chez l'insuffisant respiratoire chronique (risque d'hypercapnie après correction du stimulus hypoxémique)."}],"explanation":"Masque simple (5 à 10 L/min), masque à haute concentration avec réserve (> 8 L/min), puis canules nasales à haut débit au-delà de 15 L/min ; objectif SpO2 88-92 % et contrôle des gaz du sang sous oxygène.","src":"p. 320-321"},{"id":"p359-qcm-106","type":"QRM","rank":"B","objective":"p359-obj-14","tags":["traitement","urgence"],"difficulty":2,"stem":"Quelles situations constituent des indications pratiques de ventilation mécanique au cours d'une détresse respiratoire aiguë ?","options":[{"t":"Hypoxémie réfractaire à l'oxygénothérapie","ok":true,"why":"C'est l'autre grande indication, en plus de l'hypoventilation aiguë."},{"t":"Respiration paradoxale","ok":true,"why":"Elle traduit une faillite de la pompe ventilatoire."},{"t":"Cyanose isolée, sans autre signe de gravité clinique ou gazométrique","ok":false,"why":"La cyanose impose d'abord une oxygénothérapie immédiate ; elle ne figure pas parmi les indications de ventilation."},{"t":"Troubles de conscience","ok":true,"why":"Indication de ventilation, invasive d'emblée en cas de Glasgow < 9."},{"t":"Acidose respiratoire (hypercapnie et pH < 7,35)","ok":true,"why":"Hypoventilation aiguë menaçant le pronostic vital."}],"explanation":"La ventilation mécanique apporte un support (air + O2) sous pression par un ventilateur, via un masque (VNI) ou une sonde d'intubation (VI).","src":"p. 322"},{"id":"p359-qcm-107","type":"QRM","rank":"A","objective":"p359-obj-10","tags":["paraclinique","biologie"],"difficulty":2,"stem":"Concernant la stratégie d'investigations devant une détresse respiratoire aiguë, quelle proposition est exacte ?","options":[{"t":"Un angioscanner thoracique est réalisé systématiquement chez tout patient en détresse respiratoire","ok":false,"why":"Il est réservé aux suspicions d'embolie pulmonaire (forte probabilité ou D-dimères élevés) ou aux atteintes parenchymateuses mal définies."},{"t":"La radiographie thoracique doit précéder tout traitement symptomatique, quitte à le retarder","ok":false,"why":"La radiographie est faite au lit le plus tôt possible une fois le traitement symptomatique débuté."},{"t":"La troponine fait partie du bilan systématique de première intention, comme la NFS-plaquettes","ok":false,"why":"La troponine est demandée seulement en cas de suspicion d'ischémie myocardique."},{"t":"Le BNP est inutile car il n'apporte aucune valeur prédictive négative devant une dyspnée aiguë","ok":false,"why":"Un BNP < 100 pg/mL exclut une dyspnée aiguë d'origine cardiaque (bonne valeur prédictive négative)."},{"t":"En cas de suspicion d'EP de probabilité faible ou intermédiaire, on demande les D-dimères","ok":true,"why":"C'est la place des D-dimères dans la stratégie devant une suspicion d'embolie pulmonaire."}],"explanation":"Examens systématiques : radiographie thoracique, gazométrie avec lactate, ECG, NFS-plaquettes, ionogramme-urée-créatinine ; les autres (BNP, troponine, D-dimères, angioscanner) sont guidés par les hypothèses.","src":"p. 323"},{"id":"p359-qcm-108","type":"QRM","rank":"A","objective":"p359-obj-10","tags":["biologie","ECG"],"difficulty":2,"stem":"Concernant l'ECG et le BNP devant une détresse respiratoire aiguë, quelles propositions sont exactes ?","options":[{"t":"Le BNP ne s'élève que lorsque le ventricule gauche est dilaté","ok":false,"why":"Il s'élève lorsqu'un ventricule, gauche ou droit, est dilaté et/ou face à une augmentation de la post-charge."},{"t":"Un ECG normal est un argument important contre un OAP cardiogénique","ok":true,"why":"Il a une bonne valeur prédictive négative pour l'OAP."},{"t":"Un BNP élevé suffit à affirmer un OAP cardiogénique, sans autre examen","ok":false,"why":"Le BNP s'élève aussi dans d'autres situations (hypertension pulmonaire de l'embolie pulmonaire aiguë ou de l'exacerbation de BPCO)."},{"t":"Un BNP < 100 pg/mL exclut une dyspnée aiguë d'origine cardiaque","ok":true,"why":"Bonne valeur prédictive négative."},{"t":"Le BNP peut s'élever dans l'embolie pulmonaire aiguë","ok":true,"why":"Par hypertension pulmonaire : un ventricule droit dilaté ou face à une post-charge accrue élève le BNP."}],"explanation":"ECG normal et BNP bas écartent l'origine cardiaque ; un BNP élevé n'est pas spécifique de l'OAP cardiogénique.","src":"p. 323"},{"id":"p359-qcm-109","type":"QRM","rank":"A","objective":"p359-obj-15","tags":["clinique","urgence"],"difficulty":1,"stem":"Quel signe clinique évoque une obstruction des voies aériennes supérieures ?","options":[{"t":"Dyspnée expiratoire avec freinage et râles sibilants","ok":false,"why":"Ces signes évoquent plutôt une exacerbation d'asthme."},{"t":"Expectoration mousseuse rosée avec orthopnée","ok":false,"why":"Ils orientent vers un OAP cardiogénique."},{"t":"Abolition du murmure vésiculaire avec tympanisme à la percussion","ok":false,"why":"Ces signes évoquent un pneumothorax."},{"t":"Turgescence jugulaire avec reflux hépato-jugulaire et hépatomégalie douloureuse","ok":false,"why":"Ce sont des signes d'insuffisance cardiaque droite aiguë."},{"t":"Bradypnée inspiratoire avec temps inspiratoire allongé","ok":true,"why":"Signe clinique d'obstruction haute (le temps inspiratoire devient plus long que l'expiratoire), avec dysphonie ou aphonie et cornage ou stridor."}],"explanation":"L'obstruction des VAS est un diagnostic clinique : patient paniqué, mains au cou, sans son ; en cas d'obstruction totale, les mouvements respiratoires ne produisent aucun flux.","src":"p. 325"},{"id":"p359-qcm-110","type":"QRM","rank":"A","objective":"p359-obj-15","tags":["étiologie"],"difficulty":1,"stem":"Quelle situation est une cause d'obstruction des voies aériennes supérieures ?","options":[{"t":"Embolie pulmonaire","ok":false,"why":"C'est une étiologie de détresse respiratoire sans anomalie radiologique, non une obstruction des voies aériennes supérieures."},{"t":"Sténose trachéale, bénigne ou non","ok":true,"why":"Elle figure parmi les causes d'obstruction des VAS, avec le corps étranger, la laryngite, l'épiglottite, l'œdème de Quincke et les tumeurs laryngées."},{"t":"Exacerbation d'asthme","ok":false,"why":"C'est une étiologie « de novo » sans anomalie radiologique, non une obstruction des voies aériennes supérieures."},{"t":"Pneumothorax sous tension","ok":false,"why":"C'est une cause de détresse avec anomalies radiologiques, non une obstruction des voies aériennes supérieures."},{"t":"Œdème aigu pulmonaire cardiogénique","ok":false,"why":"C'est une cause de détresse avec anomalies radiologiques, non une obstruction des voies aériennes supérieures."}],"explanation":"Le corps étranger survient surtout aux âges extrêmes ; l'épiglottite est devenue rarissime depuis la vaccination anti-Haemophilus influenzae du nourrisson.","src":"p. 325"},{"id":"p359-qcm-111","type":"QRM","rank":"A","objective":"p359-obj-05","tags":["clinique","diagnostic"],"difficulty":2,"stem":"Un homme de 45 ans a une détresse respiratoire aiguë avec fièvre à 39,5 °C, frissons et douleur thoracique rythmée par la respiration. Quels éléments sont en faveur d'une pneumonie plutôt que d'un OAP cardiogénique ?","options":[{"t":"Orthopnée avec expectoration mousseuse","ok":false,"why":"Ces signes fonctionnels sont notés dans l'OAP cardiogénique."},{"t":"Foyer de râles crépitants à l'auscultation","ok":true,"why":"L'OAP donne des crépitants bilatéraux prédominant aux bases, non un foyer."},{"t":"Élévation du BNP ou du NT-proBNP","ok":false,"why":"Elle est un argument biologique en faveur de l'OAP cardiogénique."},{"t":"Fièvre élevée avec frissons","ok":true,"why":"L'OAP cardiogénique ne s'accompagne d'aucun signe général."},{"t":"Opacités alvéolaires le plus souvent systématisées","ok":true,"why":"Dans l'OAP, les opacités sont bilatérales, diffuses et péri-hilaires."}],"explanation":"Pneumonie : fièvre élevée, frissons, douleur rythmée par la respiration, foyer crépitant, syndrome inflammatoire, antigénuries Légionelle et pneumocoque, hémocultures. Aucun élément n'est pathognomonique ni constant.","src":"p. 326"},{"id":"p359-qcm-112","type":"QRM","rank":"A","objective":"p359-obj-05","tags":["diagnostic","clinique"],"difficulty":2,"stem":"Devant une détresse respiratoire aiguë « de novo » (embolie pulmonaire, pneumothorax, exacerbation d'asthme), quelles associations signe – diagnostic sont exactes ?","options":[{"t":"Sujet longiligne et fumeur, début brutal : exacerbation d'asthme","ok":false,"why":"Ce terrain et ce mode de début évoquent un pneumothorax ; l'asthme peut suivre une perte de contrôle."},{"t":"Radiographie normale et signes de TVP : embolie pulmonaire","ok":true,"why":"Radiographie normale ++, signes d'insuffisance ventriculaire droite et parfois de TVP."},{"t":"Distension thoracique à la radiographie : embolie pulmonaire","ok":false,"why":"La distension thoracique est décrite dans l'exacerbation d'asthme."},{"t":"Dyspnée expiratoire avec freinage : exacerbation d'asthme","ok":true,"why":"Sibilants ou silence auscultatoire dans les formes graves ; distension thoracique à la radiographie."},{"t":"Abolition du murmure vésiculaire et tympanisme : pneumothorax","ok":true,"why":"Ces signes d'examen physique sont ceux du pneumothorax."}],"explanation":"EP : facteurs de TVP, radiographie le plus souvent normale. PNO : longiligne, tabac, début brutal, hyperclarté bordée d'une ligne pleurale. Asthme : dyspnée expiratoire, freinage, distension.","src":"p. 327"},{"id":"p359-qcm-113","type":"QRM","rank":"A","objective":"p359-obj-03","tags":["définition","pièges"],"difficulty":2,"stem":"Parmi les situations suivantes, laquelle entre dans la définition gazométrique de l'insuffisance respiratoire aiguë ?","options":[{"t":"Anémie profonde avec PaO2 normale","ok":false,"why":"Hypoxie tissulaire par altération du transport de l'oxygène, sans hypoxémie : exclue de la définition."},{"t":"Intoxication au monoxyde de carbone","ok":false,"why":"Hypoxie tissulaire sans hypoxémie : exclue de la définition gazométrique."},{"t":"État de choc avec hypoperfusion tissulaire","ok":false,"why":"Hypoxie tissulaire sans hypoxémie : exclue de la définition gazométrique."},{"t":"Intoxication au cyanure (respiration cellulaire)","ok":false,"why":"Altération de la respiration cellulaire sans hypoxémie : exclue de la définition."},{"t":"Acidose respiratoire hypercapnique","ok":true,"why":"La modification aiguë du pH, notamment l'acidose respiratoire avec hypercapnie par hypoventilation alvéolaire, entre dans la définition de l'IRA."}],"explanation":"Les hypoxies tissulaires sans hypoxémie (anémie, intoxication au CO, états de choc, intoxication au cyanure, sepsis grave) n'entrent pas dans l'IRA ; d'où l'intérêt du lactate artériel quand les signes de détresse persistent.","src":"p. 317"},{"id":"p359-qcm-114","type":"QRM","rank":"B","objective":"p359-obj-08","tags":["définition"],"difficulty":2,"stem":"Quels éléments font partie de la définition du syndrome de détresse respiratoire aiguë (SDRA) ?","options":[{"t":"Confirmation systématique par biopsie pulmonaire, malgré le risque","ok":false,"why":"On ne fait jamais de biopsie (trop risquée) ; les lésions de dommage alvéolaire diffus sont connues par les données post-mortem."},{"t":"Détresse respiratoire d'évolution aiguë (délai < 7 jours)","ok":true,"why":"C'est le critère de délai."},{"t":"Pression capillaire pulmonaire (PAPO) supérieure à 15 mmHg","ok":false,"why":"La définition exige l'absence de défaillance cardiaque ou de surcharge volémique : Pcap (PAPO) < 15 mmHg."},{"t":"Opacités alvéolaires bilatérales et diffuses","ok":true,"why":"Anomalies radiologiques bien définies."},{"t":"Absence d'explication complète par un épanchement ou une atélectasie","ok":true,"why":"Les anomalies radiologiques ne doivent pas être complètement expliquées par un épanchement ou une atélectasie."}],"explanation":"SDRA : œdème lésionnel du poumon, avec détresse < 7 jours, opacités alvéolaires bilatérales diffuses et absence d'origine cardiaque ou de surcharge volémique ; conséquences : rapports ventilation-perfusion altérés et compliance diminuée.","src":"p. 327-328"},{"id":"p359-qcm-115","type":"QRM","rank":"B","objective":"p359-obj-08","tags":["étiologie"],"difficulty":1,"stem":"Quelles situations peuvent être à l'origine d'un SDRA ?","options":[{"t":"Défaillance cardiaque gauche (OAP cardiogénique)","ok":false,"why":"La définition du SDRA exclut la défaillance cardiaque : c'est le mécanisme de l'OAP cardiogénique."},{"t":"Sepsis sévère, quelle que soit la porte d'entrée","ok":true,"why":"Étiologie endogène notée comme très fréquente, quels que soient l'agent pathogène et la porte d'entrée."},{"t":"Noyade (agression exogène)","ok":true,"why":"Agression exogène (épithéliale)."},{"t":"Surcharge volémique avec élévation de la pression capillaire","ok":false,"why":"L'absence de surcharge volémique fait partie des critères du SDRA."},{"t":"Pancréatite aiguë","ok":true,"why":"Agression endogène (endothéliale), dans un contexte de réponse inflammatoire systémique."}],"explanation":"Exogènes : pneumonie (bactérienne, virale, fungique), fumées toxiques, inhalation de liquide gastrique (syndrome de Mendelson), noyade. Endogènes : sepsis sévère, pancréatite aiguë, embolie amniotique, circulation extracorporelle, transfusions massives, polytraumatisme, brûlures étendues.","src":"p. 328-329"},{"id":"p359-qcm-116","type":"QRM","rank":"A","objective":"p359-obj-12","tags":["urgence","traitement"],"difficulty":2,"stem":"Quelles mesures sont à mettre en route immédiatement et de façon concomitante devant une détresse respiratoire aiguë ?","options":[{"t":"Attendre la radiographie thoracique avant d'administrer de l'oxygène","ok":false,"why":"La radiographie se fait au lit une fois le traitement symptomatique débuté, et non avant lui."},{"t":"Surveillance continue de la SpO2 et de la fréquence cardiaque (scope)","ok":true,"why":"Mise en place immédiate de la surveillance, avec PA et fréquence respiratoire toutes les 10 minutes."},{"t":"Oxygénothérapie, toujours indiquée","ok":true,"why":"L'oxygène est toujours administré ; l'assistance ventilatoire n'est ajoutée que selon des indications précises."},{"t":"Ne débuter le bilan étiologique qu'une fois le patient totalement stabilisé","ok":false,"why":"Bilan et traitement étiologiques sont réalisés simultanément, dès que la sécurité est assurée par le traitement symptomatique."},{"t":"Appel du SAMU (hors hôpital) ou du réanimateur (à l'hôpital)","ok":true,"why":"La détresse respiratoire aiguë est une urgence médicale : l'appel est immédiat selon le lieu de prise en charge."}],"explanation":"Patient « scopé » ou installé en déchocage, oxygène toujours, appel du SAMU ou du réanimateur ; bilans et traitements étiologiques sont menés en parallèle, une fois la sécurité assurée.","src":"p. 316, 320"}],"edn":[],"trees":[],"treatments":{"data":[],"strategies":[]},"cases":[],"ecg":{"data":[],"method":""},"echo":{"data":[]},"flash":null,"pareto":{"id":"p359-pareto","points":[{"id":"p359-par-01","rank":"A","cat":"définition","text":"Détresse respiratoire = signes de **lutte** (FR > 25/min, tirage, stridor) + signes de **faillite** : un seul signe de faillite = **gravité**","src":"p. 317-318"},{"id":"p359-par-02","rank":"A","cat":"définition","text":"**IRA** = définition gazométrique : **PaO2 < 60 mmHg** + pH modifié, notamment acidose respiratoire (**PaCO2 > 45 mmHg**) ; le SDRA n'est qu'une cause de détresse","src":"p. 317"},{"id":"p359-par-03","rank":"A","cat":"gravité","text":"Signes de faillite : respiration **abdominale paradoxale** (→ discuter la ventilation), **cyanose**, astérixis / troubles de vigilance, IC droite, **choc** (PAS < 90 mmHg)","src":"p. 318-320"},{"id":"p359-par-04","rank":"A","cat":"traitement","text":"Urgence : **SAMU** ou réanimateur, scope (SpO2 + FC continues), **O2 d'emblée** avec cible **SpO2 88-92 %** ; débit ensuite adapté","src":"p. 320"},{"id":"p359-par-05","rank":"A","cat":"piège","text":"O2 à **haut débit** d'emblée **même chez le BPCO** ; contrôler les **gaz du sang sous O2** (risque d'hypercapnie)","src":"p. 320-321"},{"id":"p359-par-06","rank":"A","cat":"chiffre","text":"**SpO2 < 90 %** ou **cyanose** (Hb réduite > 5 g/dL ; peu sensible mais spécifique) → O2 immédiate ; chez le mélanoderme, regarder la **langue**","src":"p. 319"},{"id":"p359-par-07","rank":"A","cat":"examen","text":"Bilan immédiat : **radio thorax** au lit, **gaz du sang + lactate**, ECG (+ NFS, iono-urée-créatinine) ; **BNP < 100 pg/mL** exclut une cause cardiaque","src":"p. 323"},{"id":"p359-par-08","rank":"A","cat":"étiologie","text":"1re étape étiologique : éliminer une **obstruction des VAS** (paniqué, mains au cou, aphonie, stridor) ; puis **radio thorax** (opacités ?) et **gazométrie**","src":"p. 324-325"},{"id":"p359-par-09","rank":"A","cat":"étiologie","text":"Avec opacités : **pneumonie** (fièvre, foyer crépitant) vs **OAP** (apyrétique, expectoration mousseuse, crépitants bilatéraux) vs **pneumothorax** sous tension","src":"p. 325-326"},{"id":"p359-par-10","rank":"A","cat":"étiologie","text":"Sans opacités : **hypercapnie + bicarbonates > 30 mmol/L** = maladie chronique décompensée ; sinon **EP, pneumothorax, asthme** (EP : angioscanner)","src":"p. 326-327"},{"id":"p359-par-11","rank":"A","cat":"clinique","text":"Hypercapnie : céphalées, **astérixis**, somnolence (**carbonarcose**), hyperhémie conjonctivale, tremblements, sueurs, tachycardie et **HTA**","src":"p. 319-320"},{"id":"p359-par-12","rank":"B","cat":"traitement","text":"Ventiler si respiration paradoxale, **Glasgow < 9**, acidose (**pH < 7,35**), hypoxémie réfractaire ; **VNI** = BPCO acidosique + OAP ; VI d'emblée si défaillance non isolée","src":"p. 319, 322"},{"id":"p359-par-13","rank":"B","cat":"piège","text":"**Hypocapnie** avec PaO2 « normale » = hypoxémie profonde **masquée** par l'hyperventilation : refaire les gaz du sang, doser le **lactate**","src":"p. 317"},{"id":"p359-par-14","rank":"B","cat":"chiffre","text":"SDRA : début < 7 j, opacités bilatérales diffuses, **PAPO < 15 mmHg** ; PaO2/FiO2 200-300 léger, 100-200 modéré, **≤ 100 sévère** ; cause n°1 : **sepsis**","src":"p. 327-329"}]},"extra":{"semio":[],"criteres":[],"chiffres":[],"physio":[],"parcours":[],"examens":[]}});
